package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;

class QueryExecutionDeadlineTest {

	@Test
	void expirationListenersObserveZeroRemainingTime() throws Exception {
		// Exercise expiration close to the Timer's millisecond boundary. The published expiration must remain
		// authoritative even when the wall-clock timer fires before the monotonic deadline.
		for (int iteration = 0; iteration < 1_000; iteration++) {
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1)) {
				CompletableFuture<Long> remainingAtExpiration = new CompletableFuture<>();
				try (QueryExecutionDeadline.Registration registration = deadline
						.onExpiration(() -> remainingAtExpiration.complete(deadline.remainingNanos()))) {
					assertEquals(0L, remainingAtExpiration.get(5, TimeUnit.SECONDS),
							"An expiration listener must observe zero remaining time");
					assertTrue(deadline.isExpired());
				}
			}
		}
	}

	@Test
	void concurrentReadersObservePublishedExpirationEvenAfterClose() throws Exception {
		try (ExecutorService readers = Executors.newFixedThreadPool(4);
				QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1)) {
			CompletableFuture<Void> expiration = new CompletableFuture<>();
			try (QueryExecutionDeadline.Registration registration = deadline
					.onExpiration(() -> expiration.complete(null))) {
				expiration.get(5, TimeUnit.SECONDS);
				assertTrue(deadline.isExpired());
				for (int reader = 0; reader < 4; reader++) {
					assertEquals(0L, readers.submit(deadline::remainingNanos).get(5, TimeUnit.SECONDS),
							"Every thread must observe the published expiration");
				}
				deadline.close();
				assertEquals(0L, deadline.remainingNanos(), "Closing an expired deadline cannot restore time");
			}
		}
	}

	@Test
	void closingUnexpiredDeadlinePreservesUnlimitedRemainingTime() {
		QueryExecutionDeadline deadline = QueryExecutionDeadline.start(TimeUnit.MINUTES.toMillis(1));
		assertTrue(deadline.remainingNanos() > 0L);
		assertFalse(deadline.isExpired());
		deadline.close();
		assertEquals(Long.MAX_VALUE, deadline.remainingNanos());
		assertFalse(deadline.isExpired());
	}

	@Test
	void scopedContextInstallationCanClearAndRestoreNestedDeadlines() {
		QueryExecutionDeadline outer = QueryExecutionDeadline.start(TimeUnit.MINUTES.toMillis(1));
		QueryExecutionDeadline inner = QueryExecutionDeadline.start(TimeUnit.MINUTES.toMillis(1));

		try {
			assertNull(QueryExecutionDeadline.current());
			try (QueryExecutionDeadline.Scope outerScope = outer.enter()) {
				assertSame(outer, QueryExecutionDeadline.current());
				try (QueryExecutionDeadline.Scope cleared = QueryExecutionDeadline.enterScopedContext(null)) {
					assertNull(QueryExecutionDeadline.current());
					try (QueryExecutionDeadline.Scope nested = QueryExecutionDeadline.enterScopedContext(inner)) {
						assertSame(inner, QueryExecutionDeadline.current());
					}
					assertNull(QueryExecutionDeadline.current());
				}
				assertSame(outer, QueryExecutionDeadline.current());

				try (QueryExecutionDeadline.Scope legacyNull = QueryExecutionDeadline.enter(null)) {
					assertSame(outer, QueryExecutionDeadline.current(), "legacy enter(null) must remain a no-op");
				}
				assertSame(outer, QueryExecutionDeadline.current());
			}
			assertNull(QueryExecutionDeadline.current());
		} finally {
			outer.close();
			inner.close();
		}
	}
}
